const report = `# PierCast Pentwater–Caseville Pass 1 report\n\nReview date: ${REVIEW_DATE}\n\n## Outcome\n\nPass 1 is complete for Pentwater, Rogers City, Tawas City, Charlevoix, and Caseville. The package contains ${counts.research_decisions} user-facing research decisions (${counts.candidates} candidates, ${counts.holds} holds, ${counts.exclusions} exclusions) plus five fixed bluegill product-policy exclusions. No scores, runtime configuration, migration, deployment, build, public roster, or public-release manifest was changed.\n\nThe report is about city fishing conditions around covered public structures. It is not a statement that every named pier is currently fishable. Access and biological evidence remain independent, and live signs, barriers, weather, ice, vessel operations, and local authorities control.\n\n## Quantitative coverage\n\nThe preserved DNR Pier/Dock extract contains ${counts.creel_raw_rows.toLocaleString()} rows: Pentwater 1,004, Rogers City 106, Charlevoix 2,138, and explicit zero-result queries for Tawas, Tawas–East Tawas, and Caseville. A missing dashboard row is not treated as zero. Catch and harvest estimates remain separate and were not converted into scores.\n\nThe full-history DNR stocking CSV was filtered reproducibly to ${counts.stocking_raw_rows.toLocaleString()} rows in the five target counties. Every mandatory salmonid and pink-salmon cell has a complete-history result plus 5-, 10-, and 20-year windows; every positive record is classified as exact, connected-water, neighboring-port, or regional.\n\n## Salmonid conclusions\n\n${salmonidSummary.map((x) => `- ${x.city}: ${x.conclusions.join("; ")}.`).join("\n")}\n\nPink salmon remains out of catalog for all five cities. Rogers City has a current offshore/port lead but no user-facing species contract or exact recurring breakwall basis; the other four reviews remain preserved negative or unresolved leads.\n\n## Highest-value findings\n\n- Rogers City Atlantic salmon is a research candidate: direct DNR breakwall guidance, historical Pier/Dock positives, and 2026 advisory minutes establish a credible local fishery even though Atlantic salmon are not stocked there.\n- Tawas lake whitefish and burbot have exact wall/state-dock evidence. The dashboard's lack of Tawas rows did not erase these late-fall/winter opportunities.\n- Charlevoix cisco/lake herring is the strongest out-of-catalog lead: recurring 2014-2022 Pier/Dock data and exact-pier reports warrant a later full product-contract decision.\n- Caseville coho remains a Pass 2 candidate because an agency report records an exact pier catch, while its sparse evidence prevents any score now.\n- Historical stocking materially changed the queue: Tawas Chinook/brown trout, Charlevoix Atlantic/coho, and Caseville steelhead/brown/Chinook remain holds or exclusions pending exact-structure recurrence; none was promoted from stocking alone.\n\n## Bluegill policy\n\nFive compatibility records exist solely as fixed product-policy exclusions. Bluegill is not a candidate, hold, score, seasonal mode, ranking input, serialized report species, or client-visible target. Biological bluegill mentions in source data do not override the product rule.\n\n## Access boundary\n\n${cities.map((c) => `- ${c.name}: ${structures.filter((s) => s.city_id === c.id).map((s) => `${s.display_name} [${s.disposition}]`).join("; ")}.`).join("\n")}\n\n## Stocked species still held or excluded\n\n${stockedNonCandidates.length ? stockedNonCandidates.map((x) => `- ${cities.find((c) => c.id === x.city_id).name} / ${display[x.species_id]}: ${x.disposition}; ${x.explanation}`).join("\n") : "None."}\n\n## Boundary for Pass 2\n\nPass 2 may quantify only research candidates after reopening all 90 cells, resolving holds, comparing same-species anchors, and preserving all mode/geography distinctions. Raw estimate totals and stocking counts are not scores.\n`;
artifacts.set("PASS1_REPORT.md", report.replace("Every mandatory salmonid and pink-salmon cell has a complete-history result plus 5-, 10-, and 20-year windows; every positive record is classified", "All 90 user-facing city/species cells plus five pink-salmon reviews have a complete-history result and 5-, 10-, and 20-year windows; every reviewed positive record is classified").replace("Biological bluegill mentions in source data do not override the product rule.", "Biological bluegill mentions in source data do not override the product rule. A read-only system audit also found four legacy calibrated pairs that the current public v3 projection does not explicitly filter; this is a mandatory integration/release blocker. Pass 1 did not alter or deploy that runtime because this pass is prohibited from changing public visibility."));
artifacts.set("PASS2_HANDOFF.md", `# Pass 2 handoff\n\nPass 1 is complete; Pass 2 is not authorized or started.\n\nReopen all 90 user-facing cells. Begin with the ${counts.candidates} research candidates, then resolve every hold and exclusion against the raw/reduced creel, stocking, weekly-report, structure, and source ledgers. Preserve the fixed bluegill exclusions. Prioritize Rogers City Atlantic salmon, Tawas whitefish/burbot and historical salmonids, Charlevoix cisco product-contract review, and Caseville's sparse exact-pier coho record.\n\nDo not convert stocking totals, dashboard sums, generic salmon/trout labels, boat catches, or neighboring-port evidence directly into scores.\n`);
artifacts.set("README.md", `# Pentwater–Caseville PierCast onboarding: Pass 1\n\nThis directory is a generated, auditable research package for five proposed cities. Run:\n\n\`\`\`sh\n+node docs/onboarding/piercast/pentwater-caseville-2026-09-pass1/generate-pass1.mjs --check\n+\`\`\`\n\nTo re-extract the two official quantitative inputs (network required), run \`extract-source-data.mjs\`, then rerun the generator without \`--check\`. The generator owns all derived JSON, CSV, and Markdown artifacts. Raw inputs are preserved as CSV; hashes appear in reduced/review outputs.\n\nPass 1 contains no numeric calibration and makes no runtime or release changes. New-city bluegill compatibility records are fixed policy exclusions in \`bluegill-policy-exclusions.json\`; raw biological inputs may still contain source rows. The same artifact records a pre-existing four-pair runtime serialization gap as a mandatory later release blocker.\n`);
artifacts.set("validation-report.json", json({ schema_version: "piercast-pass1-validation-v1", review_date: REVIEW_DATE, overall_status: checks.every((x) => x.status === "pass") ? "pass" : "fail", counts, checks, forbidden_changes: { numeric_scores_created: false, runtime_configuration_changed: false, migration_created: false, public_visibility_changed: false, deployment_started: false, build_started: false, public_release_manifest_changed: false } }));

let drift = false;
for (const [name, content] of artifacts) {
  const target = path.join(dir, name);
  if (checkMode) {
    if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== content) { console.error(`DRIFT ${name}`); drift = true; }
  } else fs.writeFileSync(target, content);
}
if (!checks.every((x) => x.status === "pass")) {
  console.error(checks.filter((x) => x.status === "fail"));
  process.exitCode = 1;
} else if (checkMode && drift) process.exitCode = 1;
else console.log(`${checkMode ? "checked" : "generated"} ${artifacts.size} artifacts; ${checks.length} validation checks passed`);
